#!/usr/bin/env bash
set -Eeuo pipefail

# HYPER-HOST CS 1.6 — SQL MANAGER V2
# Fixes the blank SQL/Statistics page and makes the game's dedicated SQL
# manageable directly from the hosting panel.

ROOT="${1:-/root/hyper-hosting-panel}"
SID="${2:-25}"
DOMAIN="${3:-www.avito.hyper-host.pw}"

SRC_CTL="$ROOT/cs16-panel/bin/hyper-cs16-ctl"
SRC_UI="$ROOT/cs16-panel/public/index.php"
LIVE_CTL="/usr/local/sbin/hyper-cs16-ctl"
LIVE_UI="/var/www/hyper-host-sites/${DOMAIN}/public_html/index.php"
DOCROOT="/var/www/hyper-host-sites/${DOMAIN}/public_html"
PMA_DIR="$DOCROOT/phpmyadmin"

STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/hyper-cs16-sql-manager-v2-${STAMP}"
TMP="$(mktemp -d /tmp/hyper-cs16-sql-v2.XXXXXX)"
trap 'rm -rf "$TMP"' EXIT

[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "[ERROR] Run with sudo/root"; exit 1; }
for f in "$SRC_CTL" "$SRC_UI" "$LIVE_CTL" "$LIVE_UI"; do
    [[ -f "$f" ]] || { echo "[ERROR] Missing $f"; exit 2; }
done

mkdir -p "$BACKUP"
cp -a "$SRC_CTL" "$BACKUP/hyper-cs16-ctl.repo"
cp -a "$SRC_UI" "$BACKUP/index.repo.php"
cp -a "$LIVE_CTL" "$BACKUP/hyper-cs16-ctl.live"
cp -a "$LIVE_UI" "$BACKUP/index.live.php"

echo "=============================================================="
echo " HYPER-HOST CS16 SQL MANAGER V2"
echo " Repo: $ROOT"
echo " Test server: #$SID"
echo " Panel: $DOMAIN"
echo " Backup: $BACKUP"
echo "=============================================================="

cp -a "$SRC_CTL" "$TMP/src-ctl"
cp -a "$SRC_UI" "$TMP/src-ui.php"
cp -a "$LIVE_CTL" "$TMP/live-ctl"
cp -a "$LIVE_UI" "$TMP/live-ui.php"

base64 -d >"$TMP/patch.py" <<'PATCHER_B64'

PATCHER_B64

echo "[1/8] Validating patcher..."
python3 -m py_compile "$TMP/patch.py"

echo "[2/8] Applying patch to TEMP copies..."
python3 "$TMP/patch.py" "$TMP/src-ctl" "$TMP/live-ctl" "$TMP/src-ui.php" "$TMP/live-ui.php"

echo "[3/8] Syntax validation before touching live files..."
python3 -m py_compile "$TMP/src-ctl"
python3 -m py_compile "$TMP/live-ctl"
php -l "$TMP/src-ui.php" >/dev/null
php -l "$TMP/live-ui.php" >/dev/null
echo "[OK] Python/PHP syntax"

echo "[4/8] Installing patched source + live files..."
install -m 0755 "$TMP/src-ctl" "$SRC_CTL"
install -m 0644 "$TMP/src-ui.php" "$SRC_UI"
install -m 0755 "$TMP/live-ctl" "$LIVE_CTL"
install -m 0644 "$TMP/live-ui.php" "$LIVE_UI"

echo "[5/8] Installing/updating phpMyAdmin..."
DEBIAN_FRONTEND=noninteractive apt-get update -y >/dev/null
DEBIAN_FRONTEND=noninteractive apt-get install -y \
  curl ca-certificates tar openssl php-mysql php-mbstring php-xml php-zip php-gd php-curl >/dev/null

if [[ ! -f "$PMA_DIR/index.php" ]]; then
    curl -fL --retry 3 --connect-timeout 20 \
      "https://www.phpmyadmin.net/downloads/phpMyAdmin-latest-all-languages.tar.gz" \
      -o "$TMP/phpmyadmin.tar.gz"
    tar -xzf "$TMP/phpmyadmin.tar.gz" -C "$TMP"
    PMA_SRC="$(find "$TMP" -maxdepth 1 -type d -name 'phpMyAdmin-*' | head -1)"
    [[ -n "$PMA_SRC" && -f "$PMA_SRC/index.php" ]] || { echo "[ERROR] phpMyAdmin archive invalid"; exit 3; }
    [[ ! -e "$PMA_DIR" ]] || mv "$PMA_DIR" "$BACKUP/phpmyadmin.previous"
    mv "$PMA_SRC" "$PMA_DIR"
fi
mkdir -p "$PMA_DIR/tmp"
SECRET="$(openssl rand -hex 32)"
cat >"$PMA_DIR/config.inc.php" <<PHP
<?php
\$cfg['blowfish_secret'] = '${SECRET}';
\$i = 1;
\$cfg['Servers'][\$i]['auth_type'] = 'cookie';
\$cfg['Servers'][\$i]['host'] = '127.0.0.1';
\$cfg['Servers'][\$i]['port'] = '3306';
\$cfg['Servers'][\$i]['compress'] = false;
\$cfg['Servers'][\$i]['AllowNoPassword'] = false;
\$cfg['Servers'][\$i]['AllowRoot'] = false;
\$cfg['AllowArbitraryServer'] = false;
\$cfg['LoginCookieValidity'] = 14400;
\$cfg['TempDir'] = __DIR__ . '/tmp';
PHP
chown -R www-data:www-data "$PMA_DIR"
find "$PMA_DIR" -type d -exec chmod 0755 {} +
find "$PMA_DIR" -type f -exec chmod 0644 {} +
chmod 0770 "$PMA_DIR/tmp"

echo "[6/8] Checking SQL Manager commands..."
for cmd in sql-overview sql-table-info sql-query sql-external-status sql-external-enable sql-external-disable; do
    "$LIVE_CTL" --help 2>&1 | grep -q "$cmd" || { echo "[ERROR] command not registered: $cmd"; exit 4; }
done

echo "--- sql-status #$SID ---"
"$LIVE_CTL" sql-status "$SID" || true
echo "--- sql-overview #$SID ---"
"$LIVE_CTL" sql-overview "$SID" || true
echo "--- sql-external-status #$SID ---"
"$LIVE_CTL" sql-external-status "$SID" || true

echo "[7/8] Reloading PHP-FPM..."
while read -r svc; do
    [[ -n "$svc" ]] || continue
    systemctl reload "$svc" 2>/dev/null || systemctl restart "$svc" 2>/dev/null || true
done < <(systemctl list-units --type=service --state=running --no-legend | awk '/php.*fpm/ {print $1}')

echo "[8/8] HTTP checks..."
SQL_CODE="$(curl -sS -o /dev/null -w '%{http_code}' -H "Host: $DOMAIN" "http://127.0.0.1/?page=sql" || true)"
PMA_CODE="$(curl -sS -o /dev/null -w '%{http_code}' -H "Host: $DOMAIN" "http://127.0.0.1/phpmyadmin/" || true)"
echo "Panel SQL page HTTP=$SQL_CODE"
echo "phpMyAdmin HTTP=$PMA_CODE"

echo
echo "=============================================================="
echo "[SUCCESS] CS16 SQL MANAGER V2 INSTALLED"
echo
echo "Open:"
echo "  http://$DOMAIN/?page=sql"
echo
echo "The page now shows every game-server SQL database immediately."
echo "It no longer depends on player_stats/game_events/server_stats tables."
echo
echo "Selected server provides:"
echo "  - DB / user / password / AMXX sql.cfg"
echo "  - all real game DB tables"
echo "  - table rows + structure + CREATE TABLE"
echo "  - SQL console"
echo "  - phpMyAdmin"
echo "  - optional external MySQL IP allow-list"
echo
echo "Backup:"
echo "  $BACKUP"
echo "=============================================================="
